functions.calculateWeek:
function calculateWeek(index) {

    // Generate date ranges based on index
    // Starting from April 1st and creating week ranges
    if (index === 0) return ''; // First child has no date

    const startApril = new Date(2025, 3, 1); // April 1, 2025
    const startDay = new Date(startApril);
    startDay.setDate(startDay.getDate() + (index - 1) * 7); // Add weeks

    const endDay = new Date(startDay);
    endDay.setDate(endDay.getDate() + 6); // End is 6 days later

    // Format the dates
    const startDate = startDay.getDate();
    const endDate = endDay.getDate();
    const startMonth = startDay.toLocaleString('en-US', {
      month: 'short'
    });
    const endMonth = endDay.toLocaleString('en-US', {
      month: 'short'
    });

    if (startMonth === endMonth) {
      return `${startDate}-${endDate} ${startMonth}`;
    } else {
      return `${startDate} ${startMonth}-${endDate} ${endMonth}`;
    }
  }

functions.calculateCosts:
function calculateCosts(data) {
    let totalCurrentCost = 0;
    let totalProjectedCost = 0;

    data.forEach(item => {
      const allValidators = item.validator_info || [];
      const allRpcs = item.rpc_info || [];

      allValidators.forEach(val => {
        if (typeof val.current_spend === 'number') {
          totalCurrentCost += val.current_spend;
        }
        if (typeof val.projected_cost === 'number') {
          totalProjectedCost += val.projected_cost;
        }
      });

      allRpcs.forEach(rpc => {
        if (typeof rpc.current_spend === 'number') {
          totalCurrentCost += rpc.current_spend;
        }
        if (typeof rpc.projected_cost === 'number') {
          totalProjectedCost += rpc.projected_cost;
        }
      });
    });

    const formatter = new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD'
    });

    return {
      totalCurrentCost: formatter.format(totalCurrentCost),
      totalProjectedCost: formatter.format(totalProjectedCost)
    };
  }

functions.getCostsPerProtocol:
function getCostsPerProtocol(data) {
    return data.map(item => {
      let currentCost = 0;
      let projectedCost = 0;

      const allValidators = item.validator_info || [];
      const allRpcs = item.rpc_info || [];

      allValidators.forEach(val => {
        if (typeof val.current_spend === 'number') {
          currentCost += val.current_spend;
        }
        if (typeof val.projected_cost === 'number') {
          projectedCost += val.projected_cost;
        }
      });

      allRpcs.forEach(rpc => {
        if (typeof rpc.current_spend === 'number') {
          currentCost += rpc.current_spend;
        }
        if (typeof rpc.projected_cost === 'number') {
          projectedCost += rpc.projected_cost;
        }
      });

      const formatter = new Intl.NumberFormat('en-US', {
        style: 'currency',
        currency: 'USD'
      });

      return {
        protocol: item.protocol,
        validatorCount: allValidators.length,
        rpcCount: allRpcs.length,
        currentCost: formatter.format(currentCost),
        projectedCost: formatter.format(projectedCost)
      };
    });
  }

functions.giveMeAnswer:
async function giveMeAnswer(text) {
    const apiUrl = 'https://bigbrother.symbo.ls/api/mcp/query'
    const requestBody = {
      prompt: text
    }
    let responseHtml =
      '<p>Apologies, something went wrong while contacting the assistant.</p>'

    try {
      console.log('Sending request to API:', JSON.stringify(requestBody, null, 2))
      const response = await fetch(apiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(requestBody)
      })

      const responseText = await response.text() // Get raw response text for debugging
      console.log('Raw API Response:', responseText)

      if (!response.ok) {
        let errorDetail = 'Unknown error'
        try {
          const errorData = JSON.parse(responseText)
          errorDetail = errorData.detail || errorData.error || response.statusText
        } catch (e) {
          errorDetail = response.statusText || 'Failed to parse error response'
        }
        console.error('API Error:', response.status, errorDetail)
        responseHtml = `<p>Error from assistant: ${errorDetail}</p>`
        return responseHtml
      }

      try {
        const data = JSON.parse(responseText)
        return data
      } catch (e) {
        console.error('Error parsing API response:', e)
        return responseText // Return raw response if parsing fails
      }
    } catch (error) {
      console.error('Failed to fetch from API or process response:', error)
      return `<p>Failed to connect to the assistant: ${error.message}</p>`
    }
  }

